import sympy as s
from functools import lru_cache
import json
from pathlib import Path
# PS06.1: derive Einstein tensor directly from metric with nonzero constant shift.
t,x,y,z,b=s.symbols('t x y z b',real=True); a=s.Function('a')(t); X=(t,x,y,z)
g=s.Matrix([[-1+a*a*b*b,a*a*b,0,0],[a*a*b,a*a,0,0],[0,0,a*a,0],[0,0,0,a*a]])
ginv=s.simplify(g.inv())
@lru_cache(None)
def C(i,j,k):
 return s.simplify(sum(ginv[i,q]*(s.diff(g[q,k],X[j])+s.diff(g[q,j],X[k])-s.diff(g[j,k],X[q]))/2 for q in range(4)))
@lru_cache(None)
def Ric(i,j):
 return s.simplify(sum(s.diff(C(q,i,j),X[q])-s.diff(C(q,q,i),X[j])+sum(C(q,q,l)*C(l,i,j)-C(q,j,l)*C(l,q,i) for l in range(4)) for q in range(4)))
Rm=s.Matrix(4,4,Ric);scalar=s.simplify(sum(ginv[i,j]*Rm[i,j] for i in range(4) for j in range(4)))
G=s.simplify(Rm-g*scalar/2);Gup=s.simplify(ginv*G*ginv)
H=s.diff(a,t)/a;dH=s.diff(H,t)
shiftchecks={'G00':str(s.simplify(G[0,0]-(3*H*H-b*b*a*a*(2*dH+3*H*H)))), 'G0x':str(s.simplify(G[0,1]+b*a*a*(2*dH+3*H*H))), 'Gup00':str(s.simplify(Gup[0,0]-3*H*H)), 'Gup0x':str(s.simplify(Gup[0,1]+3*b*H*H)), 'metric_inverse_g00':str(ginv[0,0])}
# PS07.3: vary the original (not integrated by parts) L using 10 independent fields.
pairs=[(i,j) for i in range(4) for j in range(i,4)]
sg=[-1,1,1,1]
Ds={(mu,ab):s.Symbol('d%d_%d%d'%(mu,*ab)) for mu in range(4) for ab in pairs}
def D(mu,i,j):return Ds[(mu,tuple(sorted((i,j))))]
@lru_cache(None)
def S(mu,nu,i,j):
 return s.Symbol('s%d%d_%d%d'%(*sorted((mu,nu)),*sorted((i,j))))
da=[sum(sg[q]*D(mu,q,q) for q in range(4)) for mu in range(4)]
div=[sum(sg[mu]*sg[nu]*D(mu,mu,nu) for mu in range(4)) for nu in range(4)]
term1=sum(div[nu]*da[nu] for nu in range(4))
term2=sum(sg[rho]*sg[sigma]*sg[mu]*D(mu,rho,sigma)*D(rho,mu,sigma) for mu in range(4) for rho in range(4) for sigma in range(4))
kin=sum(sg[mu]*sg[rho]*sg[sigma]*D(mu,rho,sigma)**2 for mu in range(4) for rho in range(4) for sigma in range(4))
kintrace=sum(sg[mu]*da[mu]**2 for mu in range(4))
Lo=s.expand(s.Rational(1,2)*(term1-term2+s.Rational(1,2)*kin-s.Rational(1,2)*kintrace))
Lr=s.expand(s.Rational(1,2)*term1-s.Rational(1,2)*sum(sg[nu]*div[nu]**2 for nu in range(4))+s.Rational(1,4)*kin-s.Rational(1,4)*kintrace)
B=sum(sg[mu]*sg[nu]*S(nu,mu,mu,nu) for mu in range(4) for nu in range(4))
boxtrace=sum(sg[mu]*sg[rho]*S(mu,mu,rho,rho) for mu in range(4) for rho in range(4))
def expected(i,j):
 cov=s.Rational(1,2)*(sum(sg[mu]*(S(i,mu,mu,j)+S(j,mu,mu,i)-S(mu,mu,i,j)) for mu in range(4))-sum(sg[rho]*S(i,j,rho,rho) for rho in range(4))-(sg[i] if i==j else 0)*(B-boxtrace))
 return sg[i]*sg[j]*(1 if i==j else 2)*cov

def EL(L,ab):
 out=0
 for mu in range(4):
  mom=s.diff(L,Ds[(mu,ab)])
  for (nu,cd),var in Ds.items():
   coeff=s.diff(mom,var)
   if coeff!=0:out-=coeff*S(mu,nu,*cd)
 return s.expand(out)
ELchecks={f'{i}{j}':str(s.simplify(EL(Lo,(i,j))-expected(i,j))) for i,j in pairs}
IBPchecks={f'{i}{j}':str(s.simplify(EL(Lo,(i,j))-EL(Lr,(i,j)))) for i,j in pairs}
res={'PS06.1_shift_FLRW_exact_residuals':shiftchecks,'PS07.3_original_L_Euler_residuals':ELchecks,'PS07.3_original_vs_reduced_L_Euler_residuals':IBPchecks,'independent_covariant_components':10,'off_diagonal_variation_factor':2}
Path('/tmp/gr-ps-review/computation-results.json').write_text(json.dumps(res,indent=2))
print(json.dumps(res,indent=2))
